insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_weekly_earnings,median_hourly_earnings,annualised_median_salary,all_occupations_median_weekly,part_time_share_pct,female_share_pct,median_age,average_full_time_hours,vacancies_three_month_avg,vacancy_period,vacancy_yoy_pct,employment_growth_5y_pct,employment_growth_10y_pct,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values ('AU:warehouse-manager','2026-05-01',null,null,null,null,1852,null,null,null,null,474.66667,'2026-05-01',2.08,8.05,15.53,0,0,5,0,13,0,5,5,3,31,'career-opportunity-v1','provisional',jsonb_build_object('classification_scope','No exact current OSCA Warehouse Manager title exists. Canonical scope is related to OSCA 721132 Warehouse Supervisor operational work and OSCA 133331 Supply and Distribution Manager higher-level management.','labour_scope','Primary employment and earnings are intentionally null. Legacy ANZSCO 133611 Supply and Distribution Manager reports 30,100 workers, but that higher-level scope is context only.','vacancy_scope','Broader ANZSCO 1336 management vacancies were 474.67 in May 2026 versus 465 in May 2025, about +2.08%; no intensity or trend credit.','projection_scope','Broader ANZSCO 1336 projections are +8.05% to 2030 and +15.53% to 2035; partial growth credit.','shortage_note','Representative current warehouse-supervision and supply/distribution management scopes are No Shortage nationally in the 2025 OSL.','visa_basis','Only the related higher-level legacy ANZSCO 133611 Supply and Distribution Manager is on the current CSOL, so partial proxy credit only.','entry_level_basis','Verified logistics study routes are related preparation; progression through warehouse operations and supervision is also common.','entry_burden_basis','No statutory licence applies, but management roles typically require substantial operational experience.'),'2026-08-09') on conflict (profile_key,as_of_date) do update set employment_total=excluded.employment_total,median_weekly_earnings=excluded.median_weekly_earnings,median_hourly_earnings=excluded.median_hourly_earnings,annualised_median_salary=excluded.annualised_median_salary,all_occupations_median_weekly=excluded.all_occupations_median_weekly,part_time_share_pct=excluded.part_time_share_pct,female_share_pct=excluded.female_share_pct,median_age=excluded.median_age,average_full_time_hours=excluded.average_full_time_hours,vacancies_three_month_avg=excluded.vacancies_three_month_avg,vacancy_period=excluded.vacancy_period,vacancy_yoy_pct=excluded.vacancy_yoy_pct,employment_growth_5y_pct=excluded.employment_growth_5y_pct,employment_growth_10y_pct=excluded.employment_growth_10y_pct,shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at;
